def decode_escapes(text):
    mapping = {'n': '\n', 't': '\t', '\\': '\\'}
    result = ''
    index = 0
    while index < len(text):
        if text[index] == '\\':
            index += 1
            if index == len(text):
                raise ValueError()
            result += mapping.get(text[index], text[index])
        else:
            result += text[index]
        index += 1
    return result

